//! `contains_any` — pure any-substring match (per-method record of the pty_faults parser).

/// Whether any of `needles` occurs as a substring of `t`.
pub(crate) fn contains_any(t: &str, needles: &[&str]) -> bool {
    needles.iter().any(|n| t.contains(n))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn true_when_any_needle_is_a_substring() {
        assert!(contains_any("x uncaughtException y", &["uncaughtException", "z"]));
        assert!(contains_any("has UnhandledPromiseRejection here", &["a", "UnhandledPromiseRejection"]));
    }

    #[test]
    fn false_when_no_needle_matches_or_the_list_is_empty() {
        assert!(!contains_any("all clear", &["ERROR", "panic"]));
        assert!(!contains_any("anything", &[]));
    }
}
